// The sites this crawler visits. BankBazaar's rate-comparison page is the
// "seed": it links to one eligibility page per bank, which we follow.
return [{
  json: {
    listingUrl: 'https://www.bankbazaar.com/personal-loan-interest-rate.html',
    directPages: [
      { url: 'https://www.tatacapital.com/personal-loan.html', site: 'tatacapital' },
      { url: 'https://www.paisabazaar.com/personal-loan/', site: 'paisabazaar' },
    ],
    maxBankPages: 25,
  },
}];

const seed = $('Crawl targets').first().json;
const { tables = [], bankLinks = [] } = $input.first().json;

// The comparison table (bank -> rate range) is passed to the LLM as a hint,
// because some bank eligibility pages don't repeat the interest rate.
const rateTable = tables.find(t => /interest rate/i.test(t) && /bank/i.test(t)) || '';

// (The Code sandbox has no URL class, so resolve relative links by hand.)
const origin = seed.listingUrl.split('/').slice(0, 3).join('/');
const absolute = href => (/^https?:/.test(href) ? href : origin + (href.startsWith('/') ? '' : '/') + href);
const bankPages = [...new Set(bankLinks.map(absolute))]
  .slice(0, seed.maxBankPages)
  .map(url => ({ url, site: 'bankbazaar', rateHint: rateTable.slice(0, 3000) }));

const pages = [...bankPages, ...seed.directPages.map(p => ({ ...p, rateHint: '' }))];
return pages.map(json => ({ json }));

const page = $('For each page').item.json;
const html = $json.html || '';
if (!html) {
  return { json: { ...page, failed: true, error: $json.error?.message || 'empty response', text: '' } };
}

// Strip markup but keep table cells and list items on separate lines, so
// "Minimum income | Rs. 25,000" survives as readable text for the LLM.
const text = html
  .replace(/<(script|style|noscript|svg|header|footer|nav|form)\b[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<\/(td|th)>/gi, ' | ')
  .replace(/<(br|p|div|li|tr|h[1-6])\b[^>]*>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#8377;|&#x20b9;/gi, '₹')
  .replace(/&[a-z0-9#]+;/gi, ' ')
  .replace(/[ \t]+/g, ' ');

// Drop duplicate and very short lines (menus repeat on every page).
const seen = new Set();
const lines = text.split('\n').map(l => l.trim())
  .filter(l => l.length > 2 && !seen.has(l) && seen.add(l));

const title = (html.match(/<title[^>]*>([^<]*)/i) || [])[1]?.trim() || '';
return { json: { ...page, title, text: lines.join('\n').slice(0, 30000) } };

    const page = $('Hash page text').item.json;

    const instructions = `You extract personal-loan products from Indian lender web pages into rules for an automated matching engine.

Rules:
- Output one product per distinct personal-loan offering whose eligibility is described on the page.
- On a lender eligibility page (e.g. BankBazaar's "<Bank> personal loan eligibility"), output that bank's personal loan. Use the bank's own name as lender.
- On a marketplace overview page that only lists generic criteria, output ONE product named "<Site> Marketplace Personal Loan" with the site as lender.
- Numeric fields must be NECESSARY conditions: if thresholds differ by variant (e.g. salaried vs self-employed, with or without a salary account), use the most permissive number and describe the stricter variants in eligibility_notes.
- min_monthly_income is net monthly income in INR. Convert annual figures to monthly.
- min_credit_score only if the page states a required minimum. "Preferred" or "recommended" scores go in eligibility_notes.
- allowed_employment uses only: "Salaried", "Self-Employed" (self-employed professionals such as doctors or CAs), "Business" (business owners, self-employed non-professionals). Use null if not stated.
- eligibility_notes: short summary (max 400 characters) of requirements the numbers cannot capture and that could disqualify someone: employer type, salary account, work experience, residence stability, education, stricter conditional income tiers, preferred scores. null if there are none.
- Interest rates are % per annum. If the page has none, use the rate table hint for this lender if present.
- Never invent values. Use null when unknown.`;

    const prompt = `Page URL: ${page.url}\nPage title: ${page.title}\n\n` +
      (page.rateHint ? `Rate table hint from the BankBazaar comparison page:\n${page.rateHint}\n\n` : '') +
      `Page text:\n${page.text}`;

    const num = { type: 'NUMBER', nullable: true };
    const int = { type: 'INTEGER', nullable: true };
    const geminiRequest = {
      systemInstruction: { parts: [{ text: instructions }] },
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json',
        responseSchema: {
          type: 'OBJECT',
          properties: {
            products: {
              type: 'ARRAY',
              items: {
                type: 'OBJECT',
                properties: {
                  lender: { type: 'STRING' },
                  product_name: { type: 'STRING' },
                  interest_rate_min: num, interest_rate_max: num,
                  min_monthly_income: num,
                  min_credit_score: int, max_credit_score: int,
                  min_age: int, max_age: int,
                  allowed_employment: {
                    type: 'ARRAY', nullable: true,
                    items: { type: 'STRING', enum: ['Salaried', 'Self-Employed', 'Business'] },
                  },
                  eligibility_notes: { type: 'STRING', nullable: true },
                },
                required: ['lender', 'product_name'],
              },
            },
          },
          required: ['products'],
        },
      },
    };
    return { json: { geminiRequest } };

// Never trust LLM output blindly: parse, range-check and clean every field.
const page = $('Hash page text').item.json;
let products = [];
let error = null;
try {
  const text = $json.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') || '';
  products = JSON.parse(text).products || [];
} catch (e) {
  error = $json.error?.message || `Could not parse LLM output: ${e.message}`;
}

const inRange = (v, lo, hi) => (typeof v === 'number' && v >= lo && v <= hi ? v : null);
const EMPLOYMENT = ['Salaried', 'Self-Employed', 'Business'];

const clean = products
  .filter(p => p.lender && p.product_name)
  .map(p => {
    const employment = (p.allowed_employment || []).filter(e => EMPLOYMENT.includes(e));
    let rMin = inRange(p.interest_rate_min, 1, 60);
    let rMax = inRange(p.interest_rate_max, 1, 60);
    if (rMin && rMax && rMin > rMax) [rMin, rMax] = [rMax, rMin];
    return {
      lender: String(p.lender).trim().slice(0, 120),
      product_name: String(p.product_name).trim().slice(0, 200),
      interest_rate_min: rMin,
      interest_rate_max: rMax,
      min_monthly_income: inRange(p.min_monthly_income, 0, 10000000),
      min_credit_score: inRange(p.min_credit_score, 300, 900),
      max_credit_score: inRange(p.max_credit_score, 300, 900),
      min_age: inRange(p.min_age, 18, 80),
      max_age: inRange(p.max_age, 18, 100),
      allowed_employment: employment.length ? [...new Set(employment)] : null,
      eligibility_notes: p.eligibility_notes ? String(p.eligibility_notes).trim().slice(0, 600) || null : null,
    };
  });

// Same lender + name twice on one page: keep the first.
const unique = [...new Map(clean.map(p => [`${p.lender}|${p.product_name}`.toLowerCase(), p])).values()];

return {
  json: {
    url: page.url, site: page.site, contentHash: page.contentHash,
    error, products: unique, productsJson: JSON.stringify(unique),
  },
};
